
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_modtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_modtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.696517632000382e+00, -4.601532338760667e+00, -4.468417490540062e+00, -4.283990410890622e+00, -4.032646230351999e+00, -3.698134857650050e+00, -3.267964693269341e+00, -2.742154285141394e+00, -2.148643680882534e+00, -1.561076161892268e+00, -1.041333340960376e+00, -6.945424047142376e-01, -6.012774597660797e-01, -5.099905636342713e-01, -3.666155609933079e-01, -2.338629003566761e-01, -1.330494332688444e-01, -4.961767886210327e-02, -1.081314802073842e-02, -1.216203940591086e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


